@Component("invoice-handler")
@ProcessingGroup("invoice-processing-group")
public class InvoiceEventHandler {
	
	// core constructor
	InvoiceEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateInvoiceEvent
     */
    @EventHandler
    public void handle( CreateInvoiceEvent event) {
        entityManager.persist(new Invoice(event.getInvoiceId(), event.getInvoiceNumber(), event.getIssueDate(), event.getDueDate(), event.getTotal(), event.getCurrency(), event.getMerchant(), event.getPayments(), event.getStatus()));
    }

    /*
     * @param	event UpdateInvoiceEvent
     */
    @EventHandler
    public Invoice handle( UpdateInvoiceEvent event) {
    	entityManager.merge(new Invoice(event.getInvoiceId(), event.getInvoiceNumber(), event.getIssueDate(), event.getDueDate(), event.getTotal(), event.getCurrency(), event.getMerchant(), event.getPayments(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteInvoiceEvent
     */
    @EventHandler
    public void on( DeleteInvoiceEvent event) {
    	Invoice entity = new Invoice();
   
    	// ------------------------------------------
    	// apply the InvoiceId
    	// ------------------------------------------
    	entity.setInvoiceId( event.getInvoiceId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final InvoiceRepository invoiceEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(InvoiceEventHandler.class.getName());

}
